#include <array>
#include <cstddef>
#include <iostream>
#include <stdexcept>

int main() {
    const std::array<int, 4> original{10, 20, 30, 40};
    std::array<int, 4> guardada{1, 2, 3, 4};
    int indice1 = 0;
    int valor1 = 0;
    int indice2 = 0;
    int valor2 = 0;

    if (!(std::cin >> indice1 >> valor1 >> indice2 >> valor2)) {
        std::cout << "Error de entrada\n";
        return 0;
    }

    bool aceptado = false;
    std::array<int, 4> candidata = original;

    if (indice1 >= 0 && indice2 >= 0) {
        try {
            candidata.at(static_cast<std::size_t>(indice1)) = valor1;
            candidata.at(static_cast<std::size_t>(indice2)) = valor2;
            guardada = candidata;
            aceptado = true;
        } catch (const std::out_of_range&) {
            // El informe conserva la guardada anterior.
        }
    }

    std::cout << "Original:";
    for (std::size_t i = 0; i < original.size(); ++i) {
        std::cout << ' ' << original[i];
    }
    std::cout << "\nGuardada:";
    for (std::size_t i = 0; i < guardada.size(); ++i) {
        std::cout << ' ' << guardada[i];
    }
    std::cout << "\nAceptado: " << aceptado << '\n';

    return 0;
}

